                .collect(Collectors.groupingBy(Car::toString, Collectors.counting()));
    }

    public static Car mostPopularCar(List<Car> cars) {
        Map<String, Integer> carCounts = countCarColors(cars);
        return Stream.of(carCounts.keySet().stream().map(k -> new Car(k)).toArray(Car[]::new))
                .sorted((c1, c2) -> Integer.compare(carCounts.get(c1.getColor()), carCounts.get(c2.getColor())))
                .findFirst()
                .orElse(null);
    }
}
```

In this example, the `countCarColors` method groups cars by their color and counts the number of each. The `mostPopularCar` method finds the car with the most occurrences in the list and returns it. If there are multiple cars with the same count, it returns the first one encountered.

